import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';

const Checkout = () => {
    const navigate = useNavigate();
    const { user } = useAuth();

    // State for Shipping Info
    const [shippingInfo, setShippingInfo] = useState({
        firstName: '',
        lastName: '',
        address: '',
        city: '',
        postalCode: '',
        country: 'India',
        email: '',
        phone: ''
    });

    // State for Cart & Totals
    const [cartItems, setCartItems] = useState([]);
    const [totals, setTotals] = useState({
        subtotal: 0,
        tax: 0,
        total: 0
    });

    // 1. Load Cart from LocalStorage
    useEffect(() => {
        const items = JSON.parse(localStorage.getItem('bindass_cart')) || [];
        setCartItems(items);

        const subtotal = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
        const tax = subtotal * 0.08; // 8% Luxury Tax
        const total = subtotal + tax;

        setTotals({ subtotal, tax, total });
    }, []);

    // 2. Pre-fill User Data
    useEffect(() => {
        if (user) {
            setShippingInfo(prev => ({
                ...prev,
                email: user.email || '',
                firstName: user.displayName ? user.displayName.split(' ')[0] : '',
                lastName: user.displayName ? user.displayName.split(' ').slice(1).join(' ') : ''
            }));
        }
    }, [user]);

    // Handle Input Change
    const handleChange = (e) => {
        const { name, value } = e.target;
        setShippingInfo(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // Handle Submit
    const handleSubmit = (e) => {
        e.preventDefault();

        // Save shipping info to localStorage (optional, for persistence across reloads)
        localStorage.setItem('shipping_info', JSON.stringify(shippingInfo));

        // Navigate to Payment Step with Data
        navigate('/checkout/payment', {
            state: {
                shippingInfo,
                cartItems,
                totals
            }
        });
    };

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 font-display min-h-screen">
            <Navbar />

            <main className="max-w-7xl mx-auto px-6 py-12">
                {/* Progress Stepper */}
                <div className="mb-12 max-w-3xl">
                    <div className="flex items-center justify-between relative">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-primary/10 -z-10 -translate-y-1/2"></div>
                        <div className="flex flex-col items-center gap-2 bg-background-light light:bg-background-light pr-4">
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">1</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-primary">Shipping</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light light:bg-background-light px-4">
                            <div className="w-10 h-10 rounded-full bg-white light:bg-zinc-800 border-2 border-primary/20 text-zinc-400 flex items-center justify-center font-bold">2</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-zinc-400">Payment</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light light:bg-background-light pl-4">
                            <div className="w-10 h-10 rounded-full bg-white light:bg-zinc-800 border-2 border-primary/20 text-zinc-400 flex items-center justify-center font-bold">3</div>
                            <span className="text-xs font-semibold uppercase tracking-widest text-zinc-400">Review</span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-12">
                    {/* Left Column: Form */}
                    <div className="flex-1 space-y-8">
                        <div>
                            <h1 className="text-3xl dark:text-black font-bold mb-2">Shipping Information</h1>
                            <p className="text-slate-500 light:text-slate-400">Please enter your shipping details below.</p>
                        </div>

                        <section className="bg-white light:bg-slate-900/50 rounded-lg border border-slate-200 light:border-slate-800 p-8">
                            <div className="flex items-center justify-between mb-6">
                                <h2 className="text-sm font-bold uppercase tracking-widest flex items-center gap-3 dark:text-black">
                                    Contact Details
                                </h2>
                            </div>

                            <form className="space-y-6" onSubmit={handleSubmit}>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">First Name</label>
                                        <input
                                            required
                                            name="firstName"
                                            value={shippingInfo.firstName}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="René"
                                            type="text"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Last Name</label>
                                        <input
                                            required
                                            name="lastName"
                                            value={shippingInfo.lastName}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="Lacoste"
                                            type="text"
                                        />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Street Address</label>
                                    <input
                                        required
                                        name="address"
                                        value={shippingInfo.address}
                                        onChange={handleChange}
                                        className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                        placeholder="28 Rue de la Paix"
                                        type="text"
                                    />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">City</label>
                                        <input
                                            required
                                            name="city"
                                            value={shippingInfo.city}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="Paris"
                                            type="text"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Postal Code</label>
                                        <input
                                            required
                                            name="postalCode"
                                            value={shippingInfo.postalCode}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="75002"
                                            type="text"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Country</label>
                                        <select
                                            name="country"
                                            value={shippingInfo.country}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary text-sm font-medium cursor-pointer"
                                        >
                                            <option value="India">India</option>
                                            <option value="France">France</option>
                                            <option value="USA">USA</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Email</label>
                                        <input
                                            required
                                            name="email"
                                            value={shippingInfo.email}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="rene@lacoste.com"
                                            type="email"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-bold uppercase text-slate-500 tracking-widest">Phone</label>
                                        <input
                                            required
                                            name="phone"
                                            value={shippingInfo.phone}
                                            onChange={handleChange}
                                            className="w-full bg-background-light light:bg-slate-800 border-slate-800 border rounded-lg p-4 focus:ring-2 focus:ring-primary placeholder-slate-400 text-sm font-medium"
                                            placeholder="+33 1 23 45 67 89"
                                            type="tel"
                                        />
                                    </div>
                                </div>
                                <div className="pt-6">
                                    <button className="w-full bg-primary hover:bg-primary/90 text-white font-bold py-5 rounded-lg uppercase tracking-[0.2em] text-sm transition-all shadow-lg shadow-primary/20 flex items-center justify-center space-x-2" type="submit">
                                        <span>Continue to Payment</span>
                                        <span className="material-icons text-sm">arrow_forward</span>
                                    </button>
                                </div>
                            </form>
                        </section>
                    </div>

                    {/* Right Column: Order Summary (Sticky) */}
                    <aside className="w-full lg:w-[400px]">
                        <div className="sticky top-28 bg-white dark:bg-slate-900 p-8 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
                            <h3 className="text-lg font-bold mb-6 flex items-center justify-between">
                                Order Summary
                                <span className="bg-primary/10 text-primary text-xs px-2 py-1 rounded-full">{cartItems.length} Items</span>
                            </h3>
                            {/* Line Items */}
                            <div className="space-y-6 mb-8 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                                {cartItems.map((item, index) => (
                                    <div key={index} className="flex space-x-4">
                                        <div className="w-20 h-24 bg-background-light dark:bg-slate-800 rounded overflow-hidden flex-shrink-0">
                                            <img className="w-full h-full object-cover" alt={item.name} src={item.image} />
                                        </div>
                                        <div className="flex-1 flex flex-col justify-between py-1">
                                            <div>
                                                <h4 className="text-sm font-semibold uppercase leading-tight">{item.name}</h4>
                                                <p className="text-xs text-slate-500 mt-1">Size: {item.size} | Qty: {item.quantity}</p>
                                            </div>
                                            <div className="text-sm font-bold">₹{(item.price * item.quantity).toLocaleString()}</div>
                                        </div>
                                    </div>
                                ))}
                                {cartItems.length === 0 && (
                                    <p className="text-slate-500 text-sm">Your cart is empty.</p>
                                )}
                            </div>

                            {/* Promo Code */}
                            <div className="mb-8">
                                <div className="flex space-x-2">
                                    <input className="flex-1 bg-background-light dark:bg-slate-800 border-none rounded-lg px-4 py-3 text-sm focus:ring-1 focus:ring-primary" placeholder="Promo Code" type="text" />
                                    <button className="px-4 py-2 border border-slate-200 light:border-white rounded-lg text-xs light:text-white font-bold uppercase tracking-widest hover:bg-white light:hover:bg-slate-800 transition-colors dark:hover:text-black">Apply</button>
                                </div>
                            </div>

                            {/* Price Breakdown */}
                            <div className="space-y-3 border-t border-slate-100 dark:border-slate-800 pt-6 mb-8">
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Subtotal</span>
                                    <span>₹{totals.subtotal.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Shipping</span>
                                    <span className="text-primary font-medium">Free</span>
                                </div>
                                <div className="flex justify-between text-sm text-slate-500">
                                    <span>Estimated Tax (8%)</span>
                                    <span>₹{totals.tax.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-xl font-bold pt-4 text-slate-900 dark:text-white border-t border-slate-100 dark:border-slate-800 mt-4">
                                    <span>Total</span>
                                    <span>₹{totals.total.toLocaleString()}</span>
                                </div>
                            </div>
                        </div>
                    </aside>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Checkout;
